/// <mls fileReference="_102047_/l2/inscricaoEvento/web/contracts/eventos_abertos.defs.ts" enhancement="_blank"/>

/** Endereço do local do evento. */
export interface EnderecoLocal {
  details: {
    venue: {
      address: {
        line1?: string;
        line2?: string;
        city?: string;
        stateOrProvince?: string;
        postalCode?: string;
        countryCode?: string;
      };
    };
  };
}

/** Local do evento com nome e endereço. */
export interface LocalEvento {
  details: {
    venue: {
      name: string;
    };
  };
  address?: EnderecoLocal;
}

/** Local do evento na lista: nome e cidade. */
export interface LocalResumo {
  details: {
    venue: {
      name: string;
    };
  };
  address?: CidadeLocal;
}

/** Cidade do local do evento. */
export interface CidadeLocal {
  details: {
    venue: {
      address: {
        city?: string;
      };
    };
  };
}

/** Local e disponibilidade de vagas de um evento na lista. */
export interface EventoResumoDetails {
  venue: LocalResumo;
  readonly remainingSeats: number;
  readonly isFull: boolean;
}

/** Item da lista de eventos publicados. */
export interface EventoResumo {
  id: string;
  title: string;
  eventDate: string;
  details: EventoResumoDetails;
}

/** Descrição, local e disponibilidade de vagas do evento. */
export interface EventoDetalheDetails {
  details: {
    description: string;
    capacity: number;
  };
  venue: LocalEvento;
  readonly remainingSeats: number;
  readonly isFull: boolean;
  readonly waitlistSize: number;
}

/** Evento publicado completo para leitura e inscrição. */
export interface EventoDetalhe {
  id: string;
  title: string;
  eventDate: string;
  details: EventoDetalheDetails;
}

/** Se a inscrição ocupa vaga ou sua posição na lista de espera. */
export interface InscricaoResultadoDetails {
  readonly ocupaVaga: boolean;
  readonly posicaoListaEspera?: number;
}

/** Lotação do evento após a inscrição. */
export interface EventoInscricaoDetails {
  readonly isFull: boolean;
}

/** Evento no qual a pessoa se inscreveu. */
export interface EventoInscricao {
  title: string;
  details: EventoInscricaoDetails;
}

/** Contato com que a pessoa se inscreveu. */
export interface ParticipanteBase {
  details: {
    base: {
      readonly contacts: string;
    };
  };
}

/** Dados do participante mostrados no resultado. */
export interface ParticipanteInscricaoDetails {
  base: ParticipanteBase;
}

/** Participante da inscrição. */
export interface ParticipanteInscricao {
  details: ParticipanteInscricaoDetails;
}

/** Resultado da inscrição: código, chegada, vaga ou posição na lista de espera, evento e e-mail. */
export interface InscricaoResultado {
  id: string;
  readonly registrationCode: string;
  readonly receivedAt: string;
  details: InscricaoResultadoDetails;
  evento: EventoInscricao;
  participante: ParticipanteInscricao;
}

export interface Eventos_abertosContracts {
  /**
   * Finalidade: Carrega, ao abrir a página e a cada busca, a lista paginada de eventos publicados para a pessoa escolher qual conhecer.
   * Entrada: texto: trecho do título; dataInicio/dataFim: intervalo de data do evento; local: trecho do nome do local ou da cidade; page/pageSize: página pedida.
   * Processamento: Filtra apenas eventos com situação publicada, aplica os filtros de título, intervalo de data e local (nome ou cidade) e ordena por data do evento crescente. Para cada evento calcula vagas ocupadas (calculoVagasOcupadas: inscrições confirmadas), vagas restantes (calculoVagasRestantes: vagas menos ocupadas, nunca abaixo de zero) e lotado (listaEsperaQuandoVagasEsgotadas: ocupadas alcançaram as vagas); campos derivados, nunca gravados.
   * Saída: Página { items, page, pageSize, hasMore } de eventos com título, data, local (nome e cidade), vagas restantes e indicador de lotado, prontos para a lista.
   */
  'inscricaoEvento.eventos_abertos.listarEventosPublicados': {
    kind: 'qry';
    input: { texto?: string; dataInicio?: string; dataFim?: string; local?: string; page: number; pageSize: number };
    output: { eventos: { items: EventoResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['calculoVagasOcupadas', 'calculoVagasRestantes', 'listaEsperaQuandoVagasEsgotadas'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes', 'publicoMeuCadastro']; scope: 'own' };
  };
  /**
   * Finalidade: Carrega o evento escolhido na lista (ou aberto pela URL) com tudo que a pessoa precisa para decidir se inscrever.
   * Entrada: eventoId: id do evento selecionado na lista ou vindo da URL da página pública.
   * Processamento: Lê o evento pelo id e só o devolve se estiver publicado (caso contrário, não encontrado). Calcula vagas ocupadas (calculoVagasOcupadas), vagas restantes (calculoVagasRestantes, nunca abaixo de zero), lotado (listaEsperaQuandoVagasEsgotadas) e o tamanho da lista de espera contando as inscrições em espera do evento; tudo derivado, nada gravado.
   * Saída: O evento com título, data, descrição, local com endereço completo, número de vagas, vagas restantes, lotado e tamanho da lista de espera; também alimenta o título e o aviso de lotado na ação de inscrição.
   */
  'inscricaoEvento.eventos_abertos.obterEventoPublico': {
    kind: 'qry';
    input: { eventoId: string };
    output: { evento: EventoDetalhe };
    rules: ['calculoVagasOcupadas', 'calculoVagasRestantes', 'listaEsperaQuandoVagasEsgotadas'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes', 'publicoMeuCadastro']; scope: 'own' };
  };
  /**
   * Finalidade: Inscreve a pessoa no evento aberto com nome e e-mail, garantindo vaga ou lugar na lista de espera, e devolve o resultado para exibir na hora.
   * Entrada: eventoId: evento em que a pessoa se inscreve; name: nome informado; email: e-mail informado, usado para localizar ou criar o participante; countryCode: país da pessoa (ISO 3166-1 alfa-2); privacyConsent: consentimento de privacidade dado ao enviar os dados (exigido para BR/UE).
   * Processamento: Recusa se o evento não estiver publicado (inscricaoSomenteEventoPublicado). Localiza o participante pelo e-mail ou cria-o (register.createOrAttach) e liga o e-mail como contato. Recusa se o mesmo e-mail já tiver inscrição confirmada ou em lista de espera no evento (inscricaoUnicaPorEmailEvento, umaInscricaoPorEmailPorEvento). Na mesma transação, cria a inscrição como confirmada se houver vaga restante, senão em lista de espera (inscricaoExcedenteVaiParaListaEspera, listaEsperaQuandoVagasEsgotadas); o sistema registra o momento de chegada e emite o código. Calcula, sem gravar, ocupaVaga e a posição na lista de espera (calculoPosicaoListaEspera, ordemChegadaListaEspera: em espera do mesmo evento que chegaram antes, mais um) e recalcula vagas ocupadas, restantes, lotado e tamanho da fila do evento.
   * Saída: A inscrição com código, momento de chegada, se ocupa vaga ou a posição na lista de espera, título e lotação do evento e o e-mail usado; além do evento atualizado (detalhe e item de lista) para redesenhar a disponibilidade sem nova chamada.
   */
  'inscricaoEvento.eventos_abertos.inscreverEmEvento': {
    kind: 'cmd';
    writes: 'Inscricao.create';
    input: { eventoId: string; participante: { details: { identification: { name: string; countryCode: string }; base: { contacts: string }; person: { privacyConsent?: string } } } };
    output: { inscricao: InscricaoResultado; evento: EventoDetalhe; eventoResumo: EventoResumo };
    rules: ['inscricaoSomenteEventoPublicado', 'inscricaoUnicaPorEmailEvento', 'umaInscricaoPorEmailPorEvento', 'inscricaoExcedenteVaiParaListaEspera', 'listaEsperaQuandoVagasEsgotadas', 'ordemChegadaListaEspera', 'calculoPosicaoListaEspera', 'calculoVagasOcupadas', 'calculoVagasRestantes'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes', 'publicoMeuCadastro']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/inscricaoEvento/web/contracts/gestao_eventos.defs.ts" enhancement="_blank"/>

/** Ocupação resumida do evento na lista. */
export interface EventoResumoDetalhes {
  details: {
    capacity: number;
    readonly occupiedSeats: number;
    readonly remainingSeats: number;
  };
}

/** Linha da lista de eventos do organizador. */
export interface EventoResumo {
  id: string;
  title: string;
  eventDate: string;
  status: 'draft' | 'published';
  details: EventoResumoDetalhes;
}

/** Local do evento. */
export interface EventoLocal {
  details: {
    venue: {
      name: string;
    };
  };
}

/** Dados cadastrados e ocupação do evento. */
export interface EventoDetalheDetalhes {
  details: {
    description: string;
    capacity: number;
    readonly publishedAt?: string;
    readonly occupiedSeats: number;
    readonly remainingSeats: number;
    readonly isFull: boolean;
    readonly waitlistSize: number;
  };
  venue: EventoLocal;
}

/** Evento completo para revisão e publicação. */
export interface EventoDetalhe {
  id: string;
  version: number;
  title: string;
  eventDate: string;
  status: 'draft' | 'published';
  details: EventoDetalheDetalhes;
}

/** Identificação do participante. */
export interface ParticipanteIdentificacao {
  details: {
    identification: {
      name: string;
    };
  };
}

/** Detalhes do participante. */
export interface ParticipanteDetalhes {
  identification: ParticipanteIdentificacao;
}

/** Nome do participante inscrito. */
export interface ParticipanteRef {
  details: ParticipanteDetalhes;
}

/** Canal de e-mail. */
export interface EmailCanal {
  details: {
    contactChannel: {
      value: string;
    };
  };
}

/** Detalhes do e-mail. */
export interface EmailDetalhes {
  contactChannel: EmailCanal;
}

/** E-mail do participante inscrito. */
export interface EmailRef {
  details: EmailDetalhes;
}

/** Vaga e posição na lista de espera. */
export interface InscritoDetalhes {
  details: {
    readonly ocupaVaga: boolean;
    readonly posicaoListaEspera?: number;
  };
}

/** Linha da lista de inscritos do evento. */
export interface Inscrito {
  id: string;
  readonly registrationCode: string;
  readonly receivedAt: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  details: InscritoDetalhes;
  participante: ParticipanteRef;
  emailParticipante: EmailRef;
}

/** Momento da promoção. */
export interface PromocaoDetalhes {
  details: {
    promotedAt: string;
  };
}

/** Item da linha do tempo de promoções automáticas. */
export interface Promocao {
  id: string;
  readonly registrationCode: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  details: PromocaoDetalhes;
  participante: ParticipanteRef;
}

export interface Gestao_eventosContracts {
  /**
   * Finalidade: Lista os eventos da organização do organizador para localizar o evento a trabalhar, já com a ocupação de cada um.
   * Entrada: busca: trecho do título; status: filtra rascunho ou publicado; dataDe/dataAte: intervalo da data do evento; page/pageSize: paginação.
   * Processamento: Filtra os eventos do escopo da organização por título (contém, sem diferenciar maiúsculas), situação e intervalo de data, ordenando pela data do evento. Para cada evento calcula vagas ocupadas (calculoVagasOcupadas: inscrições confirmadas, sem canceladas nem lista de espera) e vagas restantes (calculoVagasRestantes: vagas menos ocupadas, nunca abaixo de zero); valores derivados, nunca gravados.
   * Saída: Página de eventos com título, data, situação, número de vagas, vagas ocupadas e restantes, para a lista de localização.
   */
  'inscricaoEvento.gestao_eventos.qryEventos': {
    kind: 'qry';
    input: { busca?: string; status?: 'draft' | 'published'; eventDate?: string; page: number; pageSize: number };
    output: { eventos: { items: EventoResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['calculoVagasOcupadas', 'calculoVagasRestantes'];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
  /**
   * Finalidade: Carrega o evento escolhido para revisão, ocupação e publicação, junto com as promoções automáticas da lista de espera.
   * Entrada: eventoId: id do evento selecionado na lista.
   * Processamento: Lê o evento pelo id (escopo da organização). Calcula vagas ocupadas (calculoVagasOcupadas), vagas restantes (calculoVagasRestantes), lotado quando ocupadas alcançam o número de vagas (listaEsperaQuandoVagasEsgotadas) e tamanho da lista de espera (contagem das inscrições em lista de espera); todos derivados, nunca gravados. Compõe as promoções: inscrições do evento com promotedAt preenchido (registrado por promoverPrimeiroListaEsperaAoCancelar), com nome do participante, ordenadas da mais recente para a mais antiga.
   * Saída: O evento com dados cadastrados, situação, publicado em e indicadores de ocupação, mais a linha do tempo de promoções; versão incluída para publicar.
   */
  'inscricaoEvento.gestao_eventos.qryEventoPainel': {
    kind: 'qry';
    input: { id: string };
    output: { evento: EventoDetalhe; promocoes: Promocao[] };
    rules: ['calculoVagasOcupadas', 'calculoVagasRestantes', 'listaEsperaQuandoVagasEsgotadas', 'promoverPrimeiroListaEsperaAoCancelar'];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
  /**
   * Finalidade: Lista os inscritos do evento selecionado por ordem de chegada.
   * Entrada: eventoId: evento selecionado; page/pageSize: paginação.
   * Processamento: Lista as inscrições do evento ordenadas por receivedAt ascendente (ordemChegadaListaEspera), compondo nome do participante e e-mail do cadastro mestre. Calcula ocupaVaga (inscrição confirmada) e posicaoListaEspera (calculoPosicaoListaEspera: quantas em lista de espera do mesmo evento chegaram antes, mais um; vazio fora da lista); derivados, nunca gravados.
   * Saída: Página de inscritos com código, nome, e-mail, recebida em, situação, se ocupa vaga e posição na lista de espera.
   */
  'inscricaoEvento.gestao_eventos.qryInscritosEvento': {
    kind: 'qry';
    input: { eventoId: string; page: number; pageSize: number };
    output: { inscritos: { items: Inscrito[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['ordemChegadaListaEspera', 'calculoPosicaoListaEspera'];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
  /**
   * Finalidade: Gera o CSV com todos os inscritos do evento para o organizador baixar.
   * Entrada: eventoId: evento selecionado.
   * Processamento: Lê todas as inscrições do evento (sem paginação) por ordem de chegada (ordemChegadaListaEspera), compõe nome e e-mail do participante e monta o CSV com código, nome, e-mail, situação e recebida em.
   * Saída: Nome do arquivo e conteúdo CSV, que a página entrega como download.
   */
  'inscricaoEvento.gestao_eventos.qryExportarInscritosCsv': {
    kind: 'qry';
    input: { eventoId: string };
    output: { nomeArquivo: string; readonly conteudoCsv: string };
    rules: ['ordemChegadaListaEspera'];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
  /**
   * Finalidade: Cadastra um novo evento como rascunho.
   * Entrada: title, description, eventDate, venueName (nome do local) e capacity (número de vagas) informados no formulário.
   * Processamento: Cria o evento na organização do organizador com situação draft. Ocupação é derivada (zero vagas ocupadas, restantes iguais às vagas, lista de espera vazia), nunca gravada.
   * Saída: O evento criado no formato da lista (inserido nela) e no formato de detalhe (exibido para revisão), sem nova chamada.
   */
  'inscricaoEvento.gestao_eventos.cmdSalvarEvento': {
    kind: 'cmd';
    writes: 'Evento.create';
    input: { title: string; details: { description: string; venue: { name: string }; capacity: number }; eventDate: string };
    output: { resumo: EventoResumo; evento: EventoDetalhe };
    rules: [];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
  /**
   * Finalidade: Publica o evento em rascunho, abrindo a página pública para inscrições.
   * Entrada: id e version do evento (concorrência otimista).
   * Processamento: Aplica a transição publicar (draft → published). Recusa se o evento não tiver título, descrição, data, local e número de vagas preenchidos ou se as vagas não forem maiores que zero (publicarExigeDadosCompletos). publishedAt é registrado pelo sistema na transição.
   * Saída: O evento atualizado no formato da lista e do detalhe, com situação publicado e data de publicação, para redesenhar sem nova chamada.
   */
  'inscricaoEvento.gestao_eventos.cmdPublicarEvento': {
    kind: 'cmd';
    writes: 'Evento.publicar';
    input: { id: string; version: number };
    output: { resumo: EventoResumo; evento: EventoDetalhe };
    rules: ['publicarExigeDadosCompletos'];
    access: { actors: ['organizador']; grants: ['organizadorEventos', 'organizadorInscritos']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/inscricaoEvento/web/contracts/minhas_inscricoes.defs.ts" enhancement="_blank"/>

/** Evento reduzido ao título, para linhas de resumo e linha do tempo. */
export interface EventoTitulo {
  title: string;
}

/** Evento como aparece numa linha da lista de inscrições. */
export interface EventoItem {
  title: string;
  eventDate: string;
}

/** Local do evento. */
export interface LocalEvento {
  details: {
    venue: {
      name: string;
    };
  };
}

/** Detalhes do evento mostrados no detalhe da inscrição. */
export interface EventoDetalheDetails {
  venue: LocalEvento;
}

/** Evento com data e local, para o detalhe da inscrição. */
export interface EventoDetalhe {
  title: string;
  eventDate: string;
  details: EventoDetalheDetails;
}

/** Campos derivados da situação da inscrição: se ocupa vaga e a posição na lista de espera. */
export interface InscricaoSituacao {
  details: {
    readonly ocupaVaga: boolean;
    readonly posicaoListaEspera?: number;
  };
}

/** Inscrição não cancelada no resumo, com sua situação e evento. */
export interface InscricaoResumoItem {
  id: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  details: InscricaoSituacao;
  evento: EventoTitulo;
}

/** Indicadores já calculados das inscrições da pessoa e as posições nas listas de espera. */
export interface ResumoInscricoes {
  readonly totalOcupandoVaga: number;
  readonly totalNaListaEspera: number;
  inscricoesAtivas: InscricaoResumoItem[];
}

/** Linha da lista de inscrições da pessoa. */
export interface InscricaoItem {
  id: string;
  readonly registrationCode: string;
  eventoId: string;
  readonly receivedAt: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  evento: EventoItem;
}

/** Inscrição escolhida com evento, data, local e situação derivada. */
export interface InscricaoDetalhe {
  id: string;
  readonly registrationCode: string;
  readonly receivedAt: string;
  eventoId: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  details: InscricaoSituacao;
  evento: EventoDetalhe;
}

/** Momento da promoção. */
export interface PromocaoDetails {
  details: {
    promotedAt: string;
  };
}

/** Evento da linha do tempo: inscrição da pessoa promovida da lista de espera. */
export interface PromocaoItem {
  id: string;
  readonly registrationCode: string;
  status: 'confirmed' | 'waitlisted' | 'cancelled';
  details: PromocaoDetails;
  evento: EventoTitulo;
}

export interface Minhas_inscricoesContracts {
  /**
   * Finalidade: Carrega de uma vez tudo o que a página Minhas inscrições mostra ao abrir: o resumo da situação, a primeira página da lista de inscrições e a linha do tempo de promoções.
   * Entrada: page e pageSize: página da lista de inscrições (a primeira na abertura). O participante vem da sessão (escopo own), nunca do cliente.
   * Processamento: Filtra as inscrições do participante autenticado. Resumo: conta as que ocupam vaga (status confirmed, ocupaVaga verdadeiro) e as em lista de espera (waitlisted), e lista as não canceladas com título do evento, ocupaVaga e posicaoListaEspera calculada pela regra calculoPosicaoListaEspera (inscrições waitlisted do mesmo evento com receivedAt anterior, mais um, conforme ordemChegadaListaEspera); os derivados são calculados, nunca gravados. Lista: inscrições com evento (título e data), ordenadas por receivedAt da mais recente, paginada. Promoções: inscrições com promotedAt preenchido, ordenadas por promotedAt decrescente.
   * Saída: resumo com os indicadores já calculados, inscricoes paginada ({ items, page, pageSize, hasMore }) e promocoes para a linha do tempo.
   */
  'inscricaoEvento.minhas_inscricoes.carregarMinhasInscricoes': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { resumo: ResumoInscricoes; inscricoes: { items: InscricaoItem[]; page: number; pageSize: number; hasMore: boolean }; promocoes: PromocaoItem[] };
    rules: ['calculoPosicaoListaEspera', 'ordemChegadaListaEspera'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes']; scope: 'own' };
  };
  /**
   * Finalidade: Busca as inscrições da própria pessoa pelo código ou pelo nome do evento e traz as páginas seguintes.
   * Entrada: busca: texto digitado, comparado ao código da inscrição ou ao título do evento; page e pageSize: página pedida.
   * Processamento: Restringe às inscrições do participante da sessão; filtra por registrationCode igual/iniciando pelo texto ou Evento.title contendo o texto; ordena por receivedAt decrescente; pagina.
   * Saída: inscricoes paginada que substitui a lista numa nova busca.
   */
  'inscricaoEvento.minhas_inscricoes.buscarInscricoes': {
    kind: 'qry';
    input: { busca?: string; page: number; pageSize: number };
    output: { inscricoes: { items: InscricaoItem[]; page: number; pageSize: number; hasMore: boolean } };
    rules: [];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes']; scope: 'own' };
  };
  /**
   * Finalidade: Abre a inscrição escolhida na lista para a pessoa conferir antes de cancelar.
   * Entrada: inscricaoId: id da inscrição selecionada na lista.
   * Processamento: Lê a inscrição garantindo que pertence ao participante da sessão; compõe com o evento (título, data, nome do local); calcula ocupaVaga (confirmada) e posicaoListaEspera pela regra calculoPosicaoListaEspera apenas quando waitlisted.
   * Saída: inscricao com código, recebida em, evento com data e local, situação, ocupaVaga e posição na fila; alimenta o detalhe e as ações.
   */
  'inscricaoEvento.minhas_inscricoes.obterInscricao': {
    kind: 'qry';
    input: { inscricaoId: string };
    output: { inscricao: InscricaoDetalhe };
    rules: ['calculoPosicaoListaEspera'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes']; scope: 'own' };
  };
  /**
   * Finalidade: Cancela a inscrição da própria pessoa, liberando a vaga para o primeiro da lista de espera.
   * Entrada: inscricaoId: id da inscrição a cancelar; version: versão da inscrição conhecida pela página quando a abriu, usada para controle de concorrência otimista (tratada como token opaco, não exibida ao público).
   * Processamento: cancelamentoSomentePropriaInscricao: recusa se a inscrição não pertence ao participante da sessão ou se o status não é confirmed ou waitlisted. Recusa com conflito se version difere da versão atual. Executa a transição cancelar (status cancelled, registra cancelledAt). promoverPrimeiroListaEsperaAoCancelar: se a inscrição estava confirmada, na mesma transação promove a primeira inscrição waitlisted do mesmo evento por receivedAt, registrando promotedAt. Recalcula os derivados (ocupaVaga, posicaoListaEspera) sem gravá-los.
   * Saída: inscricao atualizada para o detalhe, item para atualizar a linha da lista e resumo recalculado, para a página redesenhar sem nova chamada.
   */
  'inscricaoEvento.minhas_inscricoes.cancelarInscricao': {
    kind: 'cmd';
    writes: 'Inscricao.cancelar';
    input: { id: string; version: number };
    output: { inscricao: InscricaoDetalhe; item: InscricaoItem; resumo: ResumoInscricoes };
    rules: ['cancelamentoSomentePropriaInscricao', 'promoverPrimeiroListaEsperaAoCancelar'];
    access: { actors: ['publico']; grants: ['publicoMinhasInscricoes']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/inscricaoEvento/web/contracts/painel_organizador.defs.ts" enhancement="_blank"/>

/** Números de ocupação do evento, calculados a partir das inscrições. */
export interface OcupacaoEventoDetails {
  details: {
    capacity: number;
    readonly occupiedSeats: number;
    readonly remainingSeats: number;
    readonly waitlistSize: number;
    readonly isFull: boolean;
  };
}

/** Evento publicado com sua ocupação, para os destaques do painel. */
export interface OcupacaoEvento {
  id: string;
  title: string;
  eventDate: string;
  status: 'draft' | 'published';
  details: OcupacaoEventoDetails;
}

/** Data de publicação e vagas ocupadas do evento publicado recentemente. */
export interface PublicacaoRecenteDetails {
  details: {
    readonly publishedAt: string;
    readonly occupiedSeats: number;
  };
}

/** Evento publicado recentemente, para o resumo do painel. */
export interface PublicacaoRecente {
  id: string;
  title: string;
  status: 'draft' | 'published';
  details: PublicacaoRecenteDetails;
}

export interface Painel_organizadorContracts {
  /**
   * Finalidade: Carrega numa só chamada tudo o que o painel do organizador mostra ao abrir: a ocupação de cada evento publicado, o total de vagas ocupadas e os eventos publicados recentemente.
   * Entrada: Nenhuma entrada; o escopo é a organização do organizador autenticado.
   * Processamento: Filtra os eventos da organização com status ’published’. Para cada um calcula a partir das inscrições (nunca grava): occupiedSeats = inscrições confirmadas, sem canceladas nem em lista de espera (calculoVagasOcupadas); remainingSeats = capacity - occupiedSeats, nunca abaixo de zero (calculoVagasRestantes); waitlistSize = inscrições em lista de espera; isFull = occupiedSeats >= capacity (listaEsperaQuandoVagasEsgotadas). Ordena eventosOcupacao colocando primeiro os lotados e com fila (isFull desc, waitlistSize desc), depois os com menos vagas restantes, e por eventDate. totalVagasOcupadas é a soma de occupiedSeats dos eventos publicados, calculada no servidor. publicacoesRecentes traz os eventos publicados mais recentes ordenados por publishedAt decrescente, limitados a um número curto (ex.: 5).
   * Saída: eventosOcupacao para os destaques de ocupação; totalVagasOcupadas já somado para o resumo; publicacoesRecentes com a data de publicação. Os ids permitem navegar para a gestão do evento.
   */
  'inscricaoEvento.painel_organizador.qryPainelOrganizador': {
    kind: 'qry';
    input: {};
    output: { eventosOcupacao: OcupacaoEvento[]; readonly totalVagasOcupadas: number; publicacoesRecentes: PublicacaoRecente[] };
    rules: ['calculoVagasOcupadas', 'calculoVagasRestantes', 'listaEsperaQuandoVagasEsgotadas'];
    access: { actors: ['organizador']; grants: ['organizadorEventos']; scope: 'organization' };
  };
}

